import React, { forwardRef } from "react";
import { TouchableOpacity, Text, ViewStyle, TextStyle } from "react-native";
import { cva, type VariantProps } from "class-variance-authority";

import { DynamicIcon } from "@/components/custom/dynamic-icon";
import { WaveDotsLoader } from "@/components/loaders/wave-dots-loader";
import { ShineGradientWrapper } from "@/components/layout/shine-gradient-wrapper";

import { cn, type IconName } from "@/lib/utils";

const buttonVariants = cva("flex-row items-center justify-center border", {
    variants: {
        variant: {
            primary: "bg-primary border-transparent shadow-sm",
            secondary: "bg-secondary border-secondary-foreground shadow-none",
        },
        size: {
            sm: "min-h-[36px] px-3 gap-1.5 mb-0",
            default: "min-h-[48px] px-4 gap-2 mb-3",
            lg: "min-h-[56px] px-6 gap-2 mb-3",
        },
        fullWidth: {
            true: "w-full",
            false: "self-start",
        },
        disabled: {
            true: "bg-surface-muted shadow-none border-transparent",
        },
        roundness: {
            default: "rounded-2xl",
            full: "rounded-full",
            sm: "rounded-lg",
            none: "rounded-none",
        },
    },
    defaultVariants: {
        variant: "primary",
        size: "default",
        fullWidth: true,
        disabled: false,
        roundness: "default",
    },
});

const textVariants = cva("font-bold", {
    variants: {
        variant: {
            primary: "text-primary-foreground",
            secondary: "text-secondary-foreground",
        },
        size: {
            sm: "text-xs",
            default: "text-[13px]",
            lg: "text-[15px]",
        },
        disabled: { true: "text-foreground-disabled" },
    },
    defaultVariants: { variant: "primary", size: "default", disabled: false },
});

export interface ActionButtonProps extends VariantProps<typeof buttonVariants> {
    title: string;
    size?: "sm" | "default" | "lg";
    fullWidth?: boolean;
    icon?: IconName | string;
    iconPosition?: "pre" | "post";
    isLoading?: boolean;
    disabled?: boolean;
    onPress?: () => void;
    className?: string;
    textClassName?: string;
    iconClassName?: string;
    style?: ViewStyle;
    textStyle?: TextStyle;
    withShine?: boolean;
    hasGradient?: boolean;
    GradientColors?: [string, string, ...string[]];
}

export const ActionButton = forwardRef<
    React.ElementRef<typeof TouchableOpacity>,
    ActionButtonProps
>(
    (
        {
            title,
            icon,
            variant = "primary",
            size = "default",
            fullWidth = true,
            roundness = "default",
            iconPosition = "post",
            isLoading = false,
            disabled = false,
            onPress,
            className,
            textClassName,
            iconClassName,
            style,
            textStyle,
            withShine = false,
            hasGradient = false,
            GradientColors = ["#8870e6", "#5f84e0", "#5f84e0"],
        },
        ref,
    ) => {
        const isDisabled = disabled || isLoading;
        const isWrapped = (withShine || hasGradient) && !isDisabled;
        const iconSize = size === "sm" ? 14 : size === "lg" ? 20 : 18;

        const buttonContent = (
            <TouchableOpacity
                ref={ref}
                activeOpacity={0.9}
                disabled={isDisabled}
                onPress={onPress}
                style={style}
                className={cn(
                    buttonVariants({
                        variant,
                        size,
                        fullWidth,
                        disabled: isDisabled,
                        roundness,
                    }),
                    className,
                    isLoading ? "opacity-80" : "",
                    isWrapped ? "mb-0" : "",
                    hasGradient && !isDisabled
                        ? "bg-transparent shadow-none border-transparent"
                        : "",
                )}
            >
                {isLoading ? (
                    <WaveDotsLoader />
                ) : (
                    <>
                        {icon && iconPosition === "pre" && (
                            <DynamicIcon
                                name={icon as string}
                                size={iconSize}
                                strokeWidth={2.5}
                                className={cn(
                                    textVariants({
                                        variant,
                                        size,
                                        disabled: isDisabled,
                                    }),
                                    textClassName,
                                    iconClassName,
                                )}
                            />
                        )}
                        <Text
                            style={textStyle}
                            className={cn(
                                textVariants({
                                    variant,
                                    size,
                                    disabled: isDisabled,
                                }),
                                textClassName,
                            )}
                        >
                            {title}
                        </Text>
                        {icon && iconPosition === "post" && (
                            <DynamicIcon
                                name={icon as string}
                                size={iconSize}
                                strokeWidth={2.5}
                                className={cn(
                                    textVariants({
                                        variant,
                                        size,
                                        disabled: isDisabled,
                                    }),
                                    textClassName,
                                    iconClassName,
                                )}
                            />
                        )}
                    </>
                )}
            </TouchableOpacity>
        );

        if (isWrapped) {
            return (
                <ShineGradientWrapper
                    colors={GradientColors}
                    className={cn(
                        fullWidth ? "w-full" : "self-start",
                        size === "sm" ? "mb-0" : "mb-3",
                        roundness === "full"
                            ? "rounded-full"
                            : roundness === "sm"
                              ? "rounded-lg"
                              : roundness === "none"
                                ? "rounded-none"
                                : "rounded-2xl",
                        className,
                    )}
                    isShining={withShine}
                    hasGradient={hasGradient}
                >
                    {buttonContent}
                </ShineGradientWrapper>
            );
        }

        return buttonContent;
    },
);
ActionButton.displayName = "ActionButton";

import { View, Text, TouchableOpacity, ViewStyle } from "react-native";
import { Controller, FieldValues, UseControllerProps } from "react-hook-form";

import { DynamicIcon } from "@/components/custom/dynamic-icon";

import { cn, type IconName } from "@/lib/utils";

export interface CheckboxOption {
    value: string;
    title: string;
    subtitle?: string;
    icon?: IconName | string;
    badge?: string;
    cornerBadge?: string;
    disabled?: boolean;
}

export interface CheckboxCardProps {
    option: CheckboxOption;
    isSelected: boolean;
    onToggle: (value: string) => void;
    checkboxPosition?: "left" | "right";
    className?: string;
    style?: ViewStyle;
}

export function CheckboxCard({
    option,
    isSelected,
    onToggle,
    checkboxPosition = "right",
    className,
    style,
}: CheckboxCardProps) {
    const handlePress = () => {
        if (option?.disabled) return;
        onToggle(option?.value);
    };

    const CheckboxSquare = (
        <View
            className={cn(
                "h-5 w-5 rounded-md items-center justify-center border-2",
                isSelected
                    ? "border-primary bg-primary"
                    : "border-border bg-transparent",
                option?.disabled && "opacity-40",
            )}
        >
            {isSelected && (
                <DynamicIcon
                    name="Check"
                    size={14}
                    strokeWidth={3}
                    className="text-primary-foreground"
                />
            )}
        </View>
    );

    return (
        <TouchableOpacity
            activeOpacity={0.75}
            onPress={handlePress}
            disabled={option?.disabled}
            className={cn(
                "relative w-full min-h-[60px] flex-row items-center justify-between p-4 mb-3 rounded-2xl border",
                isSelected
                    ? "bg-primary-lighter border-primary"
                    : "bg-surface border-border",
                option?.disabled && "opacity-50",
                className,
            )}
            style={style}
        >
            {option?.cornerBadge && (
                <View className="absolute -top-3 right-4 px-2.5 py-0.5 rounded-full z-10 bg-foreground">
                    <Text className="text-[10px] font-black text-background">
                        {option?.cornerBadge}
                    </Text>
                </View>
            )}

            <View className="flex-row items-center flex-1 mr-3">
                {checkboxPosition === "left" && (
                    <View className="mr-3.5">{CheckboxSquare}</View>
                )}

                {option?.icon && (
                    <View
                        className={cn(
                            "h-11 w-11 rounded-xl items-center justify-center mr-3.5",
                            isSelected
                                ? "bg-primary-lighter"
                                : "bg-surface-muted",
                        )}
                    >
                        <DynamicIcon
                            name={option?.icon as string}
                            size={20}
                            className={
                                isSelected
                                    ? "text-primary"
                                    : "text-foreground-muted"
                            }
                        />
                    </View>
                )}

                <View className="flex-1 justify-center">
                    <View className="flex-row flex-wrap items-center gap-2">
                        <Text
                            className={cn(
                                "text-sm font-bold",
                                isSelected ? "text-primary" : "text-foreground",
                            )}
                            numberOfLines={1}
                        >
                            {option?.title}
                        </Text>

                        {option?.badge && (
                            <View className="px-2 py-0.5 rounded-md bg-primary-lighter">
                                <Text className="text-[10px] font-bold text-primary">
                                    {option?.badge}
                                </Text>
                            </View>
                        )}
                    </View>

                    {option?.subtitle && (
                        <Text
                            className="text-xs text-foreground-muted mt-0.5"
                            numberOfLines={1}
                        >
                            {option?.subtitle}
                        </Text>
                    )}
                </View>
            </View>

            {checkboxPosition === "right" && CheckboxSquare}
        </TouchableOpacity>
    );
}

// single checkbox (For simple forms, Terms & Conditions, etc.)

export interface CheckboxProps {
    checked: boolean;
    onCheckedChange: (checked: boolean) => void;
    label?: string;
    description?: string;
    disabled?: boolean;
    className?: string;
    style?: ViewStyle;
}
export function Checkbox({
    checked,
    onCheckedChange,
    label,
    description,
    disabled = false,
    className,
    style,
}: CheckboxProps) {
    const handlePress = () => {
        if (disabled) return;
        onCheckedChange(!checked);
    };

    return (
        <TouchableOpacity
            activeOpacity={0.75}
            onPress={handlePress}
            disabled={disabled}
            className={cn(
                "flex-row items-center gap-3 py-2",
                disabled && "opacity-50",
                className,
            )}
            style={style}
        >
            <View
                className={cn(
                    "h-5 w-5 rounded-md items-center justify-center border-2",
                    checked
                        ? "border-primary bg-primary"
                        : "border-border bg-transparent",
                )}
            >
                {checked && (
                    <DynamicIcon
                        name="Check"
                        size={14}
                        strokeWidth={3}
                        className="text-primary-foreground"
                    />
                )}
            </View>

            {(label || description) && (
                <View className="flex-1 justify-center">
                    {label && (
                        <Text className="text-sm font-semibold text-foreground">
                            {label}
                        </Text>
                    )}
                    {description && (
                        <Text className="text-xs text-foreground-muted mt-0.5">
                            {description}
                        </Text>
                    )}
                </View>
            )}
        </TouchableOpacity>
    );
}

// multi-select group

export interface CheckboxGroupProps {
    options: CheckboxOption[];
    values: string[];
    onValuesChange: (values: string[]) => void;
    checkboxPosition?: "left" | "right";
    label?: string;
    error?: string;
    className?: string;
    style?: ViewStyle;
}
export function CheckboxGroup({
    options,
    values = [],
    onValuesChange,
    checkboxPosition = "right",
    label,
    error,
    className,
    style,
}: CheckboxGroupProps) {
    const handleToggle = (value: string) => {
        if (values.includes(value)) {
            onValuesChange(values.filter((v) => v !== value));
        } else {
            onValuesChange([...values, value]);
        }
    };

    return (
        <View className={cn("w-full mb-3", className)} style={style}>
            {label && (
                <Text className="text-xs font-medium text-foreground-muted mb-2 ml-1">
                    {label}
                </Text>
            )}

            {options.map((option) => (
                <CheckboxCard
                    key={option.value}
                    option={option}
                    isSelected={values.includes(option.value)}
                    onToggle={handleToggle}
                    checkboxPosition={checkboxPosition}
                />
            ))}

            {error && (
                <Text className="text-xs text-destructive mt-1 ml-1 font-medium">
                    {error}
                </Text>
            )}
        </View>
    );
}

// controlled multi-select group

export interface ControlledCheckboxGroupProps<
    T extends FieldValues,
> extends UseControllerProps<T> {
    options: CheckboxOption[];
    checkboxPosition?: "left" | "right";
    label?: string;
    className?: string;
}
export function ControlledCheckboxGroup<T extends FieldValues>({
    control,
    name,
    options,
    checkboxPosition,
    label,
    className,
}: ControlledCheckboxGroupProps<T>) {
    return (
        <Controller
            control={control}
            name={name}
            render={({ field: { onChange, value }, fieldState: { error } }) => (
                <CheckboxGroup
                    options={options}
                    values={Array.isArray(value) ? value : []}
                    onValuesChange={onChange}
                    checkboxPosition={checkboxPosition}
                    label={label}
                    error={error?.message}
                    className={className}
                />
            )}
        />
    );
}

import React, { useState } from "react";
import {
    View,
    Text,
    Modal,
    Platform,
    TextInput,
    Pressable,
    TouchableOpacity,
    ViewStyle,
} from "react-native";
import {
    Contact,
    getPermissionsAsync,
    requestPermissionsAsync,
} from "expo-contacts";
import {
    useController,
    type Control,
    type FieldValues,
    type Path,
} from "react-hook-form";

import { ActionButton } from "@/components/ui/action-button";
import { DynamicIcon } from "@/components/custom/dynamic-icon";
import { cn } from "@/lib/utils";

export interface ContactsInputProps {
    nameValue: string;
    phoneValue?: string;
    onContactSelected: (name: string, phone: string) => void;
    label?: string;
    placeholder?: string;
    error?: string;
    modalTitle?: string;
    modalDescription?: string;
    allowButtonTitle?: string;
    cancelButtonTitle?: string;
    className?: string;
    style?: ViewStyle;
}

export function ContactsInput({
    nameValue,
    phoneValue,
    onContactSelected,
    label = "Contact",
    placeholder = "Enter name or pick contact",
    error,
    modalTitle = "Connect Contact",
    modalDescription = "Access to your contacts is needed to quickly select and auto-fill contact details.",
    allowButtonTitle = "Allow Contact Access",
    cancelButtonTitle = "Enter Manually Instead",
    className,
    style,
}: ContactsInputProps) {
    const [permissionModalVisible, setPermissionModalVisible] = useState(false);

    const launchPicker = async () => {
        try {
            const contact: any = await Contact.presentPicker();
            if (!contact) return;

            // Supports both getter methods (SDK 51+) and static property fallbacks
            const fullName =
                typeof contact.getFullName === "function"
                    ? await contact.getFullName()
                    : contact.name;
            const givenName =
                typeof contact.getGivenName === "function"
                    ? await contact.getGivenName()
                    : contact.firstName;
            const familyName =
                typeof contact.getFamilyName === "function"
                    ? await contact.getFamilyName()
                    : contact.lastName;
            const phones =
                typeof contact.getPhones === "function"
                    ? await contact.getPhones()
                    : contact.phoneNumbers;

            const resolvedName =
                fullName?.trim() ||
                `${givenName ?? ""} ${familyName ?? ""}`.trim() ||
                "Unknown";

            const rawPhone = phones?.[0]?.number ?? "";
            const cleanPhone = rawPhone.replace(/\s+/g, " ").trim();

            onContactSelected(resolvedName, cleanPhone);
        } catch (err) {
            console.warn("Contact picker error:", err);
        }
    };

    const triggerContactPicker = async () => {
        try {
            // iOS native contact picker can be displayed without full contact-book permission
            if (Platform.OS === "ios") {
                await launchPicker();
                return;
            }

            // Android requires explicit READ_CONTACTS permission
            const permission = await getPermissionsAsync();
            if (!permission.granted) {
                setPermissionModalVisible(true);
                return;
            }

            await launchPicker();
        } catch (err) {
            console.warn("Contact permission/picker error:", err);
            setPermissionModalVisible(true);
        }
    };

    const requestPermissionFromModal = async () => {
        try {
            const permission = await requestPermissionsAsync();
            setPermissionModalVisible(false);

            if (permission.granted) {
                await launchPicker();
            } else {
                console.warn("Contacts permission was not granted.");
            }
        } catch (err) {
            console.warn("Contact permission request error:", err);
            setPermissionModalVisible(false);
        }
    };

    const displayString = nameValue
        ? `${nameValue}${phoneValue ? ` (\${phoneValue})` : ""}`
        : "";

    return (
        <View className={cn("w-full mb-4", className)} style={style}>
            {label && (
                <Text className="text-xs font-medium text-foreground-muted mb-2">
                    {label}
                </Text>
            )}

            <View
                className={cn(
                    "flex-row items-center rounded-2xl border bg-surface overflow-hidden",
                    error ? "border-destructive" : "border-border",
                )}
            >
                <TextInput
                    className="flex-1 pl-4 py-3.5 text-sm font-medium text-foreground bg-surface"
                    placeholder={placeholder}
                    placeholderTextColor="#94a3b8"
                    value={displayString}
                    onChangeText={(val) => onContactSelected(val, "")}
                />

                <TouchableOpacity
                    activeOpacity={0.7}
                    onPress={triggerContactPicker}
                    className="p-2 mr-1.5 items-center justify-center rounded-xl border border-border bg-primary/10"
                >
                    <DynamicIcon
                        name="Contact"
                        size={20}
                        className="text-primary"
                    />
                </TouchableOpacity>
            </View>

            {error && (
                <Text className="text-xs mt-1.5 font-medium text-destructive">
                    {error}
                </Text>
            )}

            {/* Permission Bottom Sheet Modal */}
            <Modal
                transparent
                visible={permissionModalVisible}
                animationType="slide"
                statusBarTranslucent
                onRequestClose={() => setPermissionModalVisible(false)}
            >
                <Pressable
                    onPress={() => setPermissionModalVisible(false)}
                    className="flex-1 justify-end bg-black/80"
                >
                    <Pressable
                        onPress={(e) => e.stopPropagation()}
                        className="p-5 pb-8 mx-3 mb-6 rounded-[28px] border border-border bg-surface shadow-2xl"
                    >
                        <View className="items-center mb-5">
                            <View className="w-10 h-1 bg-border rounded-full mb-5" />
                            <View className="h-16 w-16 rounded-2xl bg-primary/10 border border-primary/20 items-center justify-center mb-3">
                                <DynamicIcon
                                    name="BookUser"
                                    size={30}
                                    className="text-primary"
                                />
                            </View>
                            <Text className="text-lg font-bold text-foreground text-center">
                                {modalTitle}
                            </Text>
                            <Text className="text-xs text-foreground-muted text-center mt-1.5 px-4 leading-relaxed">
                                {modalDescription}
                            </Text>
                        </View>

                        <ActionButton
                            title={allowButtonTitle}
                            variant="primary"
                            onPress={requestPermissionFromModal}
                        />
                        <ActionButton
                            title={cancelButtonTitle}
                            variant="secondary"
                            onPress={() => setPermissionModalVisible(false)}
                        />
                    </Pressable>
                </Pressable>
            </Modal>
        </View>
    );
}

export interface ControlledContactsInputProps<T extends FieldValues> {
    control: Control<T>;
    name: Path<T>;
    phoneName: Path<T>;
    label?: string;
    placeholder?: string;
    modalTitle?: string;
    modalDescription?: string;
    allowButtonTitle?: string;
    cancelButtonTitle?: string;
    className?: string;
}

export function ControlledContactsInput<T extends FieldValues>({
    control,
    name,
    phoneName,
    label = "Contact",
    placeholder,
    modalTitle,
    modalDescription,
    allowButtonTitle,
    cancelButtonTitle,
    className,
}: ControlledContactsInputProps<T>) {
    const { field: nameField, fieldState: nameFieldState } = useController({
        control,
        name,
    });

    const { field: phoneField, fieldState: phoneFieldState } = useController({
        control,
        name: phoneName,
    });

    const error =
        nameFieldState.error?.message ?? phoneFieldState.error?.message;

    const handleContactSelected = (
        resolvedName: string,
        cleanPhone: string,
    ) => {
        nameField.onChange(resolvedName);
        phoneField.onChange(cleanPhone);
        nameField.onBlur();
        phoneField.onBlur();
    };

    return (
        <ContactsInput
            nameValue={
                typeof nameField.value === "string" ? nameField.value : ""
            }
            phoneValue={
                typeof phoneField.value === "string" ? phoneField.value : ""
            }
            onContactSelected={handleContactSelected}
            label={label}
            placeholder={placeholder}
            error={error}
            modalTitle={modalTitle}
            modalDescription={modalDescription}
            allowButtonTitle={allowButtonTitle}
            cancelButtonTitle={cancelButtonTitle}
            className={className}
        />
    );
}

import React, {
    useState,
    useEffect,
    useMemo,
    useCallback,
    forwardRef,
} from "react";
import { View, Text, Pressable, ViewProps, TextStyle } from "react-native";
import { cva, type VariantProps } from "class-variance-authority";

import { DynamicIcon } from "@/components/custom/dynamic-icon";
import { cn, type IconName } from "@/lib/utils";

// --- Time Constants (in seconds) ---
const SEC_IN_MIN = 60;
const SEC_IN_HOUR = 3600;
const SEC_IN_DAY = 86400;
const SEC_IN_MONTH = 2592000; // 30 days
const SEC_IN_YEAR = 31536000; // 365 days

// --- CVA Definitions ---
const containerVariants = cva("flex-row items-center justify-center", {
    variants: {
        variant: {
            plain: "bg-transparent",
            badge: "rounded-md border",
            pill: "rounded-full border",
            boxes: "gap-1.5",
        },
        intent: {
            default: "border-border bg-surface-muted",
            primary: "border-primary/20 bg-primary/10",
            success: "border-emerald-500/20 bg-emerald-500/10",
            warning: "border-amber-500/20 bg-amber-500/10",
            destructive: "border-destructive/20 bg-destructive/10",
        },
        size: {
            xs: "px-1.5 py-0.5 gap-1",
            sm: "px-2 py-1 gap-1.5",
            default: "px-2.5 py-1 gap-1.5",
            lg: "px-3.5 py-1.5 gap-2",
        },
    },
    compoundVariants: [
        {
            variant: ["plain", "boxes"],
            className: "bg-transparent border-0 px-0 py-0",
        },
    ],
    defaultVariants: {
        variant: "plain",
        intent: "primary",
        size: "default",
    },
});

const timerTextVariants = cva("font-bold tracking-tight tabular-nums", {
    variants: {
        intent: {
            default: "text-foreground",
            primary: "text-primary",
            success: "text-emerald-500",
            warning: "text-amber-500",
            destructive: "text-destructive",
        },
        size: {
            xs: "text-[10px]",
            sm: "text-xs",
            default: "text-sm",
            lg: "text-base",
        },
    },
    defaultVariants: {
        intent: "primary",
        size: "default",
    },
});

const boxUnitVariants = cva("items-center justify-center rounded-lg border", {
    variants: {
        intent: {
            default: "bg-surface border-border",
            primary: "bg-primary/10 border-primary/30",
            success: "bg-emerald-500/10 border-emerald-500/30",
            warning: "bg-amber-500/10 border-amber-500/30",
            destructive: "bg-destructive/10 border-destructive/30",
        },
        size: {
            xs: "px-1.5 py-0.5 min-w-[26px]",
            sm: "px-2 py-1 min-w-[32px]",
            default: "px-2.5 py-1.5 min-w-[40px]",
            lg: "px-3 py-2 min-w-[48px]",
        },
    },
    defaultVariants: {
        intent: "primary",
        size: "default",
    },
});

export interface CountdownTimerProps
    extends ViewProps, VariantProps<typeof containerVariants> {
    initialYears?: number;
    initialMonths?: number;
    initialDays?: number;
    initialHours?: number;
    initialMinutes?: number;
    initialSeconds?: number;
    targetDate?: Date | string;
    format?: "colon" | "units";
    maxUnits?: number;
    padZero?: boolean;
    showSeconds?: boolean;
    icon?: IconName | string;

    timerText?: string;
    expiredText?: string;
    onResend?: () => void;
    onComplete?: () => void;

    className?: string;
    textClassName?: string;
    labelClassName?: string;
    textStyle?: TextStyle;
}

export const CountdownTimer = forwardRef<
    React.ElementRef<typeof View>,
    CountdownTimerProps
>(
    (
        {
            initialYears = 0,
            initialMonths = 0,
            initialDays = 0,
            initialHours = 0,
            initialMinutes = 0,
            initialSeconds = 0,
            targetDate,
            variant = "plain",
            intent = "primary",
            size = "default",
            format,
            maxUnits,
            padZero = false,
            showSeconds = true,
            icon,
            timerText,
            expiredText,
            onResend,
            onComplete,
            className,
            textClassName,
            labelClassName,
            style,
            textStyle,
            ...props
        },
        ref,
    ) => {
        const resolvedFormat = format ?? (onResend ? "colon" : "units");

        const calculateInitialSeconds = useCallback(() => {
            if (targetDate) {
                const target =
                    targetDate instanceof Date
                        ? targetDate.getTime()
                        : new Date(targetDate).getTime();
                return Math.max(0, Math.floor((target - Date.now()) / 1000));
            }

            const hasAnyInitial =
                initialYears > 0 ||
                initialMonths > 0 ||
                initialDays > 0 ||
                initialHours > 0 ||
                initialMinutes > 0 ||
                initialSeconds > 0;

            if (!hasAnyInitial) return 60;

            return (
                initialYears * SEC_IN_YEAR +
                initialMonths * SEC_IN_MONTH +
                initialDays * SEC_IN_DAY +
                initialHours * SEC_IN_HOUR +
                initialMinutes * SEC_IN_MIN +
                initialSeconds
            );
        }, [
            targetDate,
            initialYears,
            initialMonths,
            initialDays,
            initialHours,
            initialMinutes,
            initialSeconds,
        ]);

        const [timeLeft, setTimeLeft] = useState<number>(
            calculateInitialSeconds,
        );

        useEffect(() => {
            setTimeLeft(calculateInitialSeconds());
        }, [calculateInitialSeconds]);

        useEffect(() => {
            if (timeLeft <= 0) return;

            const interval = setInterval(() => {
                setTimeLeft((prev) => {
                    if (prev <= 1) {
                        clearInterval(interval);
                        onComplete?.();
                        return 0;
                    }
                    return prev - 1;
                });
            }, 1000);

            return () => clearInterval(interval);
        }, [timeLeft > 0, onComplete]);

        const handleResendPress = () => {
            if (timeLeft > 0 || !onResend) return;
            setTimeLeft(calculateInitialSeconds());
            onResend();
        };

        const timeUnits = useMemo(() => {
            let remaining = timeLeft;

            const years = Math.floor(remaining / SEC_IN_YEAR);
            remaining %= SEC_IN_YEAR;

            const months = Math.floor(remaining / SEC_IN_MONTH);
            remaining %= SEC_IN_MONTH;

            const days = Math.floor(remaining / SEC_IN_DAY);
            remaining %= SEC_IN_DAY;

            const hours = Math.floor(remaining / SEC_IN_HOUR);
            remaining %= SEC_IN_HOUR;

            const minutes = Math.floor(remaining / SEC_IN_MIN);
            const seconds = remaining % SEC_IN_MIN;

            const raw = [
                { key: "y", value: years },
                { key: "mo", value: months },
                { key: "d", value: days },
                { key: "h", value: hours },
                { key: "m", value: minutes },
                ...(showSeconds ? [{ key: "s", value: seconds }] : []),
            ];

            const minKeep = resolvedFormat === "colon" ? 2 : 1;
            const firstNonZeroIdx = raw.findIndex((u) => u.value > 0);
            const sliceStart =
                firstNonZeroIdx === -1
                    ? Math.max(0, raw.length - minKeep)
                    : Math.min(
                          firstNonZeroIdx,
                          Math.max(0, raw.length - minKeep),
                      );

            const active = raw.slice(sliceStart);
            return maxUnits ? active.slice(0, maxUnits) : active;
        }, [timeLeft, showSeconds, resolvedFormat, maxUnits]);

        const formattedString = useMemo(() => {
            if (resolvedFormat === "colon") {
                return timeUnits
                    .map((u) => String(u.value).padStart(2, "0"))
                    .join(":");
            }
            return timeUnits
                .map((u) => {
                    const val = padZero
                        ? String(u.value).padStart(2, "0")
                        : String(u.value);
                    return `${val}${u.key}`;
                })
                .join(" ");
        }, [timeUnits, resolvedFormat, padZero]);

        const iconSize =
            size === "xs" ? 10 : size === "sm" ? 12 : size === "lg" ? 16 : 14;

        const isExpired = timeLeft <= 0;
        const fallbackExpiredText = onResend
            ? "Resend Now"
            : expiredText || formattedString;

        return (
            <View
                ref={ref}
                className={cn(
                    containerVariants({ variant, intent, size }),
                    className,
                )}
                style={style}
                {...props}
            >
                {icon && (
                    <DynamicIcon
                        name={icon as string}
                        size={iconSize}
                        className={cn(
                            timerTextVariants({ intent, size }),
                            textClassName,
                        )}
                    />
                )}
                {timerText && (
                    <Text
                        className={cn(
                            "text-foreground-muted",
                            size === "xs"
                                ? "text-[10px]"
                                : size === "sm"
                                  ? "text-xs"
                                  : "text-sm",
                            labelClassName,
                        )}
                    >
                        {timerText}{" "}
                    </Text>
                )}

                {variant === "boxes" && !isExpired ? (
                    <View className="flex-row items-center gap-1.5">
                        {timeUnits.map((unit) => (
                            <View
                                key={unit.key}
                                className={boxUnitVariants({ intent, size })}
                            >
                                <Text
                                    style={textStyle}
                                    className={cn(
                                        timerTextVariants({ intent, size }),
                                        textClassName,
                                    )}
                                >
                                    {padZero
                                        ? String(unit.value).padStart(2, "0")
                                        : unit.value}
                                    <Text className="text-[10px] font-semibold opacity-75">
                                        {unit.key}
                                    </Text>
                                </Text>
                            </View>
                        ))}
                    </View>
                ) : (
                    <Pressable
                        onPress={handleResendPress}
                        disabled={!isExpired || !onResend}
                    >
                        <Text
                            style={textStyle}
                            className={cn(
                                timerTextVariants({ intent, size }),
                                isExpired && onResend && "underline",
                                textClassName,
                            )}
                        >
                            {isExpired ? fallbackExpiredText : formattedString}
                        </Text>
                    </Pressable>
                )}
            </View>
        );
    },
);
