import { HomeHeader } from "./home-header";
import { NavigatorHeader } from "./navigator-header";

import { cn } from "@/lib/utils";

export interface MainWrapperProps {
    children: React.ReactNode;
    homeHeader?: boolean;
    navigatorHeader?: boolean;
    heading?: string;
    topSpacing?: boolean;
    className?: string;
    fullScreen?: boolean;
    bottomSpacing?: number;
    navigatorOptions?: {
        rightBlock?: [{ name?: string; onPress?: () => void; icon?: string }];
    };
    homeHeaderOptions?: any;
}

export function MainWrapper({
    children,
    homeHeader = false,
    navigatorHeader = true,
    heading,
    topSpacing,
    className,
    fullScreen = false,
    navigatorOptions,
    bottomSpacing = 10,
    homeHeaderOptions,
    ...props
}: MainWrapperProps) {
    const router = useRouter();
    const insets = useSafeAreaInsets();

    const safeBottomPadding = Math.min(insets.bottom, bottomSpacing);

    const handleHomeHeaderRedirects = (route: string) => {
