import React from "react";
import { Text, TouchableOpacity, View, ViewStyle } from "react-native";

import { DynamicIcon } from "@/components/custom/dynamic-icon";

import { cn } from "@/lib/utils";

export interface SectionWrapperProps {
    children: React.ReactNode;
    type?: "default" | "bordered";
    title?: string;
    showInfoIcon?: boolean;
    onInfoPress?: () => void;
    rightTitle?: string;
    rightType?: "text" | "navigate" | "chip";
    rightAction?: () => void;
    className?: string;
    style?: ViewStyle;
    contentClassName?: string;
}

export function SectionWrapper({
    children,
    type = "default",
    title,
    showInfoIcon = false,
    onInfoPress,
    rightTitle,
    rightType = "text",
    rightAction,
    className,
    style,
    contentClassName,
}: SectionWrapperProps) {
    const renderInfoIcon = () => {
        if (!showInfoIcon && !onInfoPress) return null;

        const IconElement = (
            <DynamicIcon
                name="Info"
                size={16}
                className="text-foreground-muted ml-1"
            />
        );

        if (onInfoPress) {
            return (
                <TouchableOpacity
                    activeOpacity={0.7}
                    onPress={onInfoPress}
                    hitSlop={10}
                >
                    {IconElement}
                </TouchableOpacity>
            );
        }
        return IconElement;
    };

    return (
        <View className={cn("w-full mb-6", className)} style={style}>
            {/* Header Row */}
            <View className="flex-row items-center justify-between mb-3 px-2">
                <View className="flex-row items-center gap-1.5">
                    {title && (
                        <Text className="text-base font-bold text-foreground tracking-tight">
                            {title}
                        </Text>
                    )}
                    {renderInfoIcon()}
                </View>

                {/* Right Action */}
                {rightTitle &&
                    (rightType === "text" ? (
                        <Text className="text-sm font-bold text-foreground-muted">
                            {rightTitle}
                        </Text>
                    ) : (
                        <TouchableOpacity
                            className={cn(
                                "flex-row items-center gap-1 px-2.5 py-1 rounded-full",
                                rightType === "chip" && "bg-surface-muted",
                            )}
                            onPress={rightAction}
                            activeOpacity={0.7}
                            disabled={!rightAction}
                        >
                            <Text className="text-sm font-bold text-foreground-muted">
                                {rightTitle}
                            </Text>
                            <DynamicIcon
                                name="ChevronRight"
                                size={12}
                                className="text-foreground-muted"
                            />
                        </TouchableOpacity>
                    ))}
            </View>

            {/* Content */}
            <View
                className={cn(
                    type === "bordered" &&
                        "border border-border rounded-2xl p-4 bg-background",
                    contentClassName,
                )}
            >
                {children}
            </View>
        </View>
    );
}

import React, { useState, useCallback, useEffect } from "react";
import {
    View,
    Text,
    Pressable,
    LayoutChangeEvent,
    ViewStyle,
} from "react-native";
import {
    Controller,
    type FieldValues,
    type UseControllerProps,
} from "react-hook-form";
import Animated, {
    withSpring,
    withTiming,
    useSharedValue,
    useAnimatedStyle,
} from "react-native-reanimated";
import * as Haptics from "expo-haptics";

import { DynamicIcon } from "@/components/custom/dynamic-icon";

import { cn, type IconName } from "@/lib/utils";

const INDICATOR_SPRING = {
    damping: 24,
    stiffness: 300,
    mass: 0.6,
    overshootClamping: true,
};

export interface SegmentedOption<T extends string = string> {
    label: string;
    value: T;
    icon?: IconName | string;
}

export interface SegmentedControlProps<T extends string = string> {
    options: SegmentedOption<T>[];
    value?: T;
    defaultValue?: T;
    onChange?: (value: T) => void;
    label?: string;
    className?: string;
    style?: ViewStyle;
    size?: "sm" | "md" | "lg";
    error?: string;
    disabled?: boolean;
}

export function SegmentedControl<T extends string = string>({
    options,
    value: controlledValue,
    defaultValue,
    onChange,
    label,
    className,
    style,
    size = "md",
    error,
    disabled = false,
}: SegmentedControlProps<T>) {
    const [internalValue, setInternalValue] = useState<T>(
        defaultValue ?? options[0]?.value,
    );

    const isControlled = controlledValue !== undefined;
    const activeValue = isControlled ? controlledValue : internalValue;

    const [containerWidth, setContainerWidth] = useState(0);

    const activeIndex = Math.max(
        0,
        options.findIndex((option) => option.value === activeValue),
    );

    const translateX = useSharedValue(0);
    const indicatorWidth = useSharedValue(0);
    const indicatorOpacity = useSharedValue(0);

    const handleContainerLayout = useCallback(
        (event: LayoutChangeEvent) => {
            const { width } = event.nativeEvent.layout;
            if (width !== containerWidth) {
                setContainerWidth(width);
            }
        },
        [containerWidth],
    );

    useEffect(() => {
        if (containerWidth > 0 && options?.length > 0) {
            const segmentWidth = containerWidth / options.length;
            const targetX = activeIndex * segmentWidth;

            indicatorWidth.value = withSpring(segmentWidth, INDICATOR_SPRING);
            translateX.value = withSpring(targetX, INDICATOR_SPRING);
            indicatorOpacity.value = withTiming(1, { duration: 150 });
        }
    }, [
        containerWidth,
        activeIndex,
        options,
        indicatorWidth,
        translateX,
        indicatorOpacity,
    ]);

    const animatedPillStyle = useAnimatedStyle(() => ({
        width: indicatorWidth.value,
        opacity: indicatorOpacity.value,
        transform: [{ translateX: translateX.value }],
    }));

    const handleSelect = (val: T) => {
        if (disabled || val === activeValue) return;

        Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);

        if (!isControlled) {
            setInternalValue(val);
        }
        onChange?.(val);
    };

    return (
        <View className={cn("w-full mb-4", className)} style={style}>
            {label && (
                <Text className="text-xs font-medium text-foreground-muted mb-2">
                    {label}
                </Text>
            )}

            <View
                className={cn(
                    "w-full rounded-2xl p-1 border bg-surface-muted",
                    error ? "border-destructive" : "border-border",
                    disabled && "opacity-50",
                )}
            >
                <View
                    onLayout={handleContainerLayout}
                    className="relative flex-row items-center"
                >
                    <Animated.View
                        pointerEvents="none"
                        style={animatedPillStyle}
                        className="absolute top-0 bottom-0 left-0 rounded-xl border border-border/40 bg-surface shadow-sm"
                    />

                    {options?.map((option) => {
                        const isSelected = option?.value === activeValue;

                        return (
                            <Pressable
                                key={option?.value}
                                onPress={() => handleSelect(option?.value)}
                                disabled={disabled}
                                className={cn(
                                    "flex-1 flex-row items-center justify-center gap-2 z-10",
                                    size === "sm" && "px-2 py-1.5",
                                    size === "md" && "px-3 py-2",
                                    size === "lg" && "px-4 py-3",
                                )}
                            >
                                {option?.icon && (
                                    <DynamicIcon
                                        name={option.icon as string}
                                        size={
                                            size === "sm"
                                                ? 14
                                                : size === "lg"
                                                  ? 18
                                                  : 16
                                        }
                                        strokeWidth={2.5}
                                        className={cn(
                                            isSelected
                                                ? "text-foreground"
                                                : "text-foreground-muted",
                                        )}
                                    />
                                )}
                                <Text
                                    className={cn(
                                        "font-semibold tracking-tight transition-colors",
                                        size === "sm" && "text-[11px]",
                                        size === "md" && "text-xs",
                                        size === "lg" && "text-sm",
                                        isSelected
                                            ? "text-foreground font-bold"
                                            : "text-foreground-muted",
                                    )}
                                    numberOfLines={1}
                                >
                                    {option?.label}
                                </Text>
                            </Pressable>
                        );
                    })}
                </View>
            </View>

            {error && (
                <Text className="text-xs mt-1.5 font-medium text-destructive ml-1">
                    {error}
                </Text>
            )}
        </View>
    );
}

export interface ControlledSegmentedControlProps<
    T extends FieldValues,
    V extends string = string,
> extends UseControllerProps<T> {
    label?: string;
    options: SegmentedOption<V>[];
    size?: "sm" | "md" | "lg";
    className?: string;
    style?: ViewStyle;
}

export function ControlledSegmentedControl<
    T extends FieldValues,
    V extends string = string,
>({
    control,
    name,
    options,
    label,
    size,
    disabled,
    className,
    style,
}: ControlledSegmentedControlProps<T, V>) {
    return (
        <Controller
            control={control}
            name={name}
            disabled={disabled}
            render={({ field: { onChange, value }, fieldState: { error } }) => (
                <SegmentedControl
                    options={options}
                    value={value as V}
                    onChange={onChange}
                    label={label}
                    size={size}
                    error={error?.message}
                    disabled={disabled}
                    className={className}
                    style={style}
                />
            )}
        />
    );
}

import React, { useEffect } from "react";
import { View, StyleSheet, ViewStyle } from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import Animated, {
    useSharedValue,
    useAnimatedStyle,
    withRepeat,
    withTiming,
    Easing,
    withDelay,
} from "react-native-reanimated";

import { cn } from "@/lib/utils";

export interface ShineGradientWrapperProps {
    colors: [string, string, ...string[]]; // Requires at least 2 colors
    children: React.ReactNode;
    className?: string;
    style?: ViewStyle;
    isShining?: boolean;
    hasGradient?: boolean;
}

export function ShineGradientWrapper({
    colors,
    children,
    className,
    style,
    isShining = true,
    hasGradient = false,
}: ShineGradientWrapperProps) {
    const shimmerPosition = useSharedValue(-300);

    useEffect(() => {
        if (isShining) {
            shimmerPosition.value = withRepeat(
                withDelay(
                    1500,
                    withTiming(400, {
                        duration: 1200,
                        easing: Easing.inOut(Easing.ease),
                    }),
                ),
                -1,
                false,
            );
        }
    }, [isShining]);

    const shimmerStyle = useAnimatedStyle(() => {
        return {
            transform: [{ translateX: shimmerPosition.value }],
        };
    });

    return (
        <View
            className={cn("overflow-hidden relative", className)}
            style={style}
        >
            <LinearGradient
                colors={hasGradient ? colors : ["transparent", "transparent"]}
                start={{ x: 0, y: 0 }}
                end={{ x: 1, y: 1 }}
                style={{ width: "100%", justifyContent: "center" }}
            >
                {isShining && (
                    <Animated.View
                        style={[StyleSheet.absoluteFill, shimmerStyle]}
                        pointerEvents="none"
                    >
                        <LinearGradient
                            colors={[
                                "rgba(255,255,255,0)",
                                "rgba(255,255,255,0.4)",
                                "rgba(255,255,255,0)",
                            ]}
                            start={{ x: 0, y: 0 }}
                            end={{ x: 1, y: 0 }}
                            style={[
                                StyleSheet.absoluteFill,
                                {
                                    width: 150,
                                    transform: [{ skewX: "-20deg" }],
                                },
                            ]}
                        />
                    </Animated.View>
                )}

                <View className="z-10 w-full justify-center">{children}</View>
            </LinearGradient>
        </View>
    );
}

import React, { useRef, forwardRef } from "react";
import {
    Text,
    View,
    Animated,
    PanResponder,
    LayoutChangeEvent,
    ViewProps,
} from "react-native";

import { DynamicIcon } from "@/components/custom/dynamic-icon";

import { cn } from "@/lib/utils";

export interface SlideToActionProps extends ViewProps {
    text?: string;
    onComplete: () => void;
}

const KNOB_SIZE = 54;
const TRACK_PADDING = 6;

export const SlideToAction = forwardRef<
    React.ElementRef<typeof View>,
    SlideToActionProps
>(
    (
        {
            text = "Swipe right to get started",
            onComplete,
            className,
            ...props
        },
        ref,
    ) => {
        const pan = useRef(new Animated.Value(0)).current;
        const maxSlideRef = useRef(0);

        const panResponder = useRef(
            PanResponder.create({
                onStartShouldSetPanResponder: () => true,
                onPanResponderMove: (_, gestureState) => {
                    const maxSlide = maxSlideRef.current;
                    if (
                        maxSlide > 0 &&
                        gestureState.dx > 0 &&
                        gestureState.dx <= maxSlide
                    ) {
                        pan.setValue(gestureState.dx);
                    }
                },
                onPanResponderRelease: (_, gestureState) => {
                    const maxSlide = maxSlideRef.current;
                    if (maxSlide > 0 && gestureState.dx > maxSlide * 0.75) {
                        Animated.timing(pan, {
                            toValue: maxSlide,
                            duration: 150,
                            useNativeDriver: true,
                        }).start(() => {
                            onComplete();
                        });
                    } else {
                        Animated.spring(pan, {
                            toValue: 0,
                            useNativeDriver: true,
                            bounciness: 12,
                        }).start();
                    }
                },
            }),
        ).current;

        const handleLayout = (event: LayoutChangeEvent) => {
            const { width } = event.nativeEvent.layout;
            maxSlideRef.current = width - KNOB_SIZE - TRACK_PADDING * 2;
        };

        return (
            <View
                ref={ref}
                className={cn(
                    "w-full h-[66px] rounded-full justify-center px-[6px] bg-primary",
                    className,
                )}
                onLayout={handleLayout}
                {...props}
            >
                <View className="absolute flex-row items-center justify-center gap-2 w-full text-center ml-5">
                    <Text className="text-lg font-semibold z-[1] text-foreground">
                        {text}
                    </Text>
                    <DynamicIcon
                        name="MoveRight"
                        size={24}
                        className="text-foreground"
                    />
                </View>

                <Animated.View
                    className="w-[54px] h-[54px] rounded-full bg-foreground justify-center items-center shadow-md shadow-black/20"
                    style={[{ transform: [{ translateX: pan }], elevation: 3 }]}
                    {...panResponder.panHandlers}
                >
                    <DynamicIcon
                        name="ChevronsRight"
                        size={24}
                        className="text-primary"
                    />
                </Animated.View>
            </View>
        );
    },
);
SlideToAction.displayName = "SlideToAction";

import React, { useEffect, forwardRef } from "react";
import { ViewProps } from "react-native";
import Animated, {
    Easing,
    withRepeat,
    withTiming,
    useSharedValue,
    useAnimatedStyle,
} from "react-native-reanimated";

import { cn } from "@/lib/utils";

export interface SpinnerLoaderProps extends Omit<ViewProps, "style"> {
    color?: string;
    size?: number;
    strokeWidth?: number;
    className?: string;
    style?: any;
}

export const SpinnerLoader = forwardRef<
    React.ElementRef<typeof Animated.View>,
    SpinnerLoaderProps
>(
    (
        {
            color = "#ffffff", // Default to white, perfectly overridden by the prop
            size = 24,
            strokeWidth = 3,
            className,
            style,
            ...props
        },
        ref,
    ) => {
        const rotation = useSharedValue(0);

        useEffect(() => {
            rotation.value = withRepeat(
                withTiming(360, { duration: 800, easing: Easing.linear }),
                -1,
            );
        }, []);

        const animatedStyle = useAnimatedStyle(() => ({
            transform: [{ rotateZ: `${rotation.value}deg` }],
        }));

        return (
            <Animated.View
                ref={ref}
                className={cn("justify-center items-center", className)}
                style={[
                    animatedStyle,
                    {
                        width: size,
                        height: size,
                        borderRadius: size / 2,
                        borderWidth: strokeWidth,
                        borderColor: `${color}40`, // 25% opacity for the track
                        borderTopColor: color, // Solid color for the spinning head
                    },
                    style,
                ]}
                {...props}
            />
        );
    },
);
SpinnerLoader.displayName = "SpinnerLoader";

